import Foundation
import MLXLMCommon
import MLXLMServer

/// Per-request Super output: the reference reasoning channel, native tool
/// frames and the shared tool/structured-output validators. Streaming exposes
/// reasoning and plain content as they arrive; tool calls, forced-tool output
/// and JSON content are withheld until validation. A complete response is
/// split once at the end, as the reference non-streaming parser does. Total
/// generated bytes are bounded. Grants no sampler grammar or tool execution.
struct NemotronSuperLocalOutput {
    enum Failure: Error { case invalidRequest, limit, alreadyFinished, malformedToolFrame }

    struct Result: Equatable {
        let content: String
        let reasoning: String?
        let calls: [ToolCall]
    }

    let plan: NemotronSuperRequestPlan
    let streaming: Bool
    /// Nil when content carries no tool frames to parse.
    private let handler: BatchedToolStreamHandler?
    private var channel: NemotronSuperReasoningChannel
    private var raw = ""
    private var content = ""
    private var reasoning = ""
    private var receivedBytes = 0
    private var finished = false
    private let maximumBytes: Int

    init(plan: NemotronSuperRequestPlan, streaming: Bool, maximumBytes: Int = 1 << 20) throws {
        guard maximumBytes > 0, maximumBytes <= 16 << 20 else { throw Failure.invalidRequest }
        self.plan = plan
        self.streaming = streaming
        // With no tool declared under auto choice the prompt offers no tools,
        // so a literal `<tool_call>` is answer text, as in the reference
        // server. Otherwise frames always parse: a call that `none` or the
        // declarations do not allow fails validation instead of reaching the
        // client as raw XML.
        let offersNoTools = plan.toolPolicy.mode == .auto && plan.toolPolicy.tools?.isEmpty != false
        handler = offersNoTools ? nil : BatchedToolStreamHandler(format: .nemotron,
            tools: plan.toolPolicy.tools?.map { $0.toolSpec() })
        channel = NemotronSuperReasoningChannel(controls: plan.controls)
        self.maximumBytes = maximumBytes
    }

    private var withholdsContent: Bool {
        plan.toolPolicy.requiresToolCall || plan.request.responseFormat?.requiresJSONOutput == true
    }

    /// Events safe to expose now; empty while buffering.
    mutating func append(_ chunk: String) throws -> [MLXServerGenerationEvent] {
        guard !finished else { throw Failure.alreadyFinished }
        guard chunk.utf8.count <= maximumBytes - receivedBytes else {
            finished = true; throw Failure.limit
        }
        receivedBytes += chunk.utf8.count
        guard streaming else { raw += chunk; return [] }
        do { return try route(channel.stream(chunk)) }
        catch { finished = true; throw error }
    }

    /// Remaining events, then validated tool calls; nothing is exposed if
    /// validation fails.
    mutating func finish() throws -> (events: [MLXServerGenerationEvent], result: Result) {
        guard !finished else { throw Failure.alreadyFinished }
        finished = true
        var events: [MLXServerGenerationEvent] = []
        if streaming {
            events = try route(channel.finishStream())
            // The streamed reasoning stays; its copy is content and passes the
            // same tool and response-format checks as any other.
            if channel.promotesUnterminatedReasoning, !reasoning.isEmpty {
                events += try route([.init(content: reasoning, reasoningContent: nil)])
            }
        } else {
            let split = channel.complete(raw)
            reasoning = split.reasoning ?? ""
            _ = try route([.init(content: split.content ?? "", reasoningContent: nil)])
        }
        let calls = handler?.finish() ?? []
        let residual = handler?.takeResidualText() ?? ""
        let forced = plan.toolPolicy.requiresToolCall
        // route refuses mid-stream parse failures, so any failure here is the
        // end-of-stream remainder: a complete opening tag is an unterminated
        // frame; a bare `<to…` prefix was only withheld while being probed.
        let unterminated = (handler?.parseFailureCount ?? 0) > 0
            && Self.frameOpenings.contains(where: residual.contains)
        guard !unterminated, !forced || ToolChoiceEnforcementPolicy.isFramingWhitespace(residual)
        else { throw Failure.malformedToolFrame }
        try ToolConstraintValidation.validate(calls, prepared: plan.toolPolicy)
        // A response format shapes the final answer; a turn that calls tools
        // is not one, so its text (none for a forced choice) passes unchanged.
        let answer = forced ? "" : content + residual
        let validatedContent = calls.isEmpty
            ? try OpenAIResponseFormatSupport.normalizedContent(answer, for: plan.request.responseFormat) : answer
        let validatedReasoning = reasoning.isEmpty ? nil : reasoning
        // Streamed reasoning and plain streamed content (never JSON-normalized)
        // already left through route; only the parser's residual text remains.
        let pending = streaming && !withholdsContent ? residual : validatedContent
        let pendingReasoning = streaming ? nil : validatedReasoning
        if !pending.isEmpty || pendingReasoning != nil {
            events.append(.parsed(.init(content: pending, reasoningContent: pendingReasoning)))
        }
        events += calls.map { .toolCall($0) }
        return (events, Result(content: validatedContent, reasoning: validatedReasoning, calls: calls))
    }

    /// Reasoning is never parsed for tools; content passes the tool parser
    /// when the request has one.
    private mutating func route(_ pieces: [ParsedReasoning]) throws -> [MLXServerGenerationEvent] {
        var events: [MLXServerGenerationEvent] = []
        for piece in pieces {
            if let text = piece.reasoningContent, !text.isEmpty {
                reasoning += text
                events.append(.parsed(.init(content: "", reasoningContent: text)))
            }
            var visible = ""
            if let handler {
                for segment in Self.tagSegments(piece.content) {
                    let text = handler.processChunk(segment)
                    // The shared parser returns a failed frame as text; refuse
                    // it before that text can be exposed.
                    guard handler.parseFailureCount == 0 else { throw Failure.malformedToolFrame }
                    visible += text ?? ""
                }
            } else {
                visible = piece.content
            }
            guard !visible.isEmpty else { continue }
            if plan.toolPolicy.requiresToolCall {
                guard ToolChoiceEnforcementPolicy.isFramingWhitespace(visible) else {
                    throw MultiModelBatchSchedulerEngineError.toolChoiceViolation(
                        "forced tool_choice produced visible text before a validated call")
                }
                continue
            }
            content += visible
            if streaming && !withholdsContent {
                events.append(.parsed(.init(content: visible, reasoningContent: nil)))
            }
        }
        return events
    }

    private static let frameOpenings = ["<tool_call>", "<function="]

    /// The shared tagged-frame processor keeps text that precedes a `<` in the
    /// same chunk only until it returns; if the frame is still open, that text
    /// is lost. Starting every segment at a `<` leaves no such prefix.
    static func tagSegments(_ text: String) -> [String] {
        var segments: [String] = []
        var start = text.startIndex
        for index in text.indices where text[index] == "<" && index != start {
            segments.append(String(text[start..<index]))
            start = index
        }
        if start < text.endIndex { segments.append(String(text[start...])) }
        return segments
    }
}
